import { execSync } from 'child_process';
import fs from 'fs';
const W='';
const FILES={'includes/class-pet-profile.php':''};
const TOKG=process.env.GH_TOKEN, REPO=process.env.GH_REPO||'raimis079-creator/petshop-bridge';
const U=process.env.WP_USER||'', P=(process.env.WP_APP_PASS||'').replace(/\s+/g,'');
const AUTH='-u "'+U+':'+P+'"';
function wj(m,path,body){fs.writeFileSync('/tmp/wb.json', JSON.stringify(body));
  return execSync('curl -sk --max-time 150 '+AUTH+' -X '+m+' -H "Content-Type: application/json" --data-binary @/tmp/wb.json "https://dev.avesa.lt/wp-json/'+path+'"',{maxBuffer:50e6,timeout:170000}).toString();}
function putB64(name,b64){const u='https://api.github.com/repos/'+REPO+'/contents/screenshots/'+name;let s='';
 for(let i=0;i<6;i++){try{const j=JSON.parse(execSync('curl -s -H "Authorization: Bearer '+TOKG+'" "'+u+'?n='+Math.random()+'"',{maxBuffer:50e6}).toString());if(j.sha)s=j.sha;}catch(e){}
  fs.writeFileSync('/tmp/pj.json',JSON.stringify({message:'r',content:b64,...(s?{sha:s}:{})}));
  const c=execSync('curl -s -o /dev/null -w "%{http_code}" -X PUT -H "Authorization: Bearer '+TOKG+'" -d @/tmp/pj.json "'+u+'"',{maxBuffer:50e6}).toString().trim();
  if(c==='200'||c==='201')return c; execSync('sleep 3');}return 'fail';}
const o={marker:'S246'}; let sid=null;
try{
  let mk=null;
  for(let a=0;a<2;a++){ try{ mk=wj('POST','code-snippets/v1/snippets',{name:'S246 (temp)',code:Buffer.from(W,'base64').toString('utf8'),scope:'front-end',active:true,priority:5}); break; }catch(e){ execSync('sleep 5'); } }
  try{sid=JSON.parse(mk).id;}catch(e){o.mk=String(mk).slice(0,120);}
  execSync('sleep 5');
  fs.writeFileSync('/tmp/payload.json', JSON.stringify({files:FILES}));
  for(let a=0;a<3;a++){ try{const r=execSync('curl -sk --max-time 120 -X POST -H "Content-Type: application/json" --data-binary @/tmp/payload.json "https://dev.avesa.lt/?ps_dep218=Dp218x"',{maxBuffer:20e6,timeout:140000}).toString();
    const j=r.slice(r.indexOf('{'),r.lastIndexOf('}')+1); o.write=j; if(j.includes('class-pet-profile')) break; }catch(e){o.write='ERR '+a;} execSync('sleep 5'); }
  if(sid!==null){ try{execSync('curl -sk --max-time 60 '+AUTH+' -X DELETE "https://dev.avesa.lt/wp-json/code-snippets/v1/snippets/'+sid+'"');}catch(e){} sid=null; }
  // VERIFIKACIJA: pakeiciam produkta ir tikrinam ar snapshot persirase
  const vphp='<?php add_action("wp_loaded",function(){ if(!isset($_GET["ps_v246"])||$_GET["ps_v246"]!=="V246x") return; wp_set_current_user(1); global $wpdb; $t=$wpdb->prefix."ps_pets"; $o=array(); '
   +'$pid=(int)$wpdb->get_var("SELECT id FROM $t WHERE pet_name=\'dekas\' AND deleted_at IS NULL LIMIT 1"); '
   +'$prod=(int)$wpdb->get_var("SELECT product_id FROM {$wpdb->prefix}ps_feeding_map WHERE is_active=1 ORDER BY product_id ASC LIMIT 1"); '
   +'$pobj=wc_get_product($prod); $o["naujas"]=array("id"=>$prod,"n"=>$pobj?mb_substr($pobj->get_name(),0,42):null); '
   +'$routes=rest_get_server()->get_routes(); $cb=null; foreach($routes as $rt=>$hs){ if(strpos($rt,"pet-profile/")!==false){ foreach($hs as $h){ if(isset($h["callback"])){$cb=$h["callback"];break 2;} } } } '
   +'if($cb){ $r=new WP_REST_Request("PATCH"); $r->set_url_params(array("id"=>$pid,"pet_id"=>$pid)); '
   +'$r->set_body(json_encode(array("pet_id"=>$pid,"primary_product_id"=>$prod))); $r->set_header("content-type","application/json"); '
   +'$res=call_user_func($cb,$r); $o["patch"]=is_wp_error($res)?$res->get_error_message():"OK"; } '
   +'$o["po"]=$wpdb->get_row($wpdb->prepare("SELECT primary_product_id,primary_product_name,primary_product_sku,primary_product_package FROM $t WHERE id=%d",$pid),ARRAY_A); '
   +'header("Content-Type: application/json"); echo json_encode($o); exit; });';
  const mk2=wj('POST','code-snippets/v1/snippets',{name:'V246 (temp)',code:vphp,scope:'front-end',active:true,priority:5});
  let sid2=null; try{sid2=JSON.parse(mk2).id;}catch(e){}
  execSync('sleep 5');
  try{ const r=execSync('curl -sk --max-time 60 "https://dev.avesa.lt/?ps_v246=V246x"',{maxBuffer:8e6,timeout:75000}).toString();
    const i=r.indexOf('{'),k=r.lastIndexOf('}'); if(i>=0&&k>i) o.ver=JSON.parse(r.slice(i,k+1)); }catch(e){ o.ve=String(e).slice(0,100); }
  if(sid2!==null){ try{execSync('curl -sk --max-time 60 '+AUTH+' -X DELETE "https://dev.avesa.lt/wp-json/code-snippets/v1/snippets/'+sid2+'"');}catch(e){} }
}catch(e){ o.err=String(e).slice(0,200); }
try{ if(sid!=null) execSync('curl -sk --max-time 60 '+AUTH+' -X DELETE "https://dev.avesa.lt/wp-json/code-snippets/v1/snippets/'+sid+'"'); }catch(e){}
putB64('s246.json', Buffer.from(JSON.stringify(o)).toString('base64'));
console.log('done');
